import java.util.*;

public class Main {
    static final String[] DEFAULT_LIFECYCLE = {
            "validate", "initialize", "generate-sources", "process-sources", "generate-resources",
            "process-resources", "compile", "process-classes", "generate-test-sources",
            "process-test-sources", "generate-test-resources", "process-test-resources",
            "test-compile", "process-test-classes", "test", "prepare-package", "package",
            "pre-integration-test", "integration-test", "post-integration-test", "verify",
            "install", "deploy"
    };

    static final Map<String, String[]> BINDINGS = new LinkedHashMap<>();
    static {
        BINDINGS.put("process-resources", new String[]{"resources:resources"});
        BINDINGS.put("compile", new String[]{"compiler:compile"});
        BINDINGS.put("process-test-resources", new String[]{"resources:testResources"});
        BINDINGS.put("test-compile", new String[]{"compiler:testCompile"});
        BINDINGS.put("test", new String[]{"surefire:test"});
        BINDINGS.put("package", new String[]{"jar:jar"});
        BINDINGS.put("verify", new String[]{"failsafe:verify"});
        BINDINGS.put("install", new String[]{"install:install"});
        BINDINGS.put("deploy", new String[]{"deploy:deploy"});
    }

    static void runTo(String target, List<String> log) {
        log.clear();
        for (String p : DEFAULT_LIFECYCLE) {
            String[] gs = BINDINGS.get(p);
            if (gs != null) for (String g : gs) log.add(p + " -> " + g);
            if (p.equals(target)) return;
        }
    }

    public static void main(String[] args) {
        System.out.println("=== default lifecycle phases in order ===");
        for (int i = 0; i < DEFAULT_LIFECYCLE.length; i++)
            System.out.printf("  %2d. %s%n", i + 1, DEFAULT_LIFECYCLE[i]);

        List<String> log = new ArrayList<>();
        System.out.println();
        System.out.println("=== mvn compile ===");
        runTo("compile", log);
        log.forEach(l -> System.out.println("  " + l));

        System.out.println();
        System.out.println("=== mvn package ===");
        runTo("package", log);
        log.forEach(l -> System.out.println("  " + l));

        System.out.println();
        System.out.println("=== mvn install ===");
        runTo("install", log);
        log.forEach(l -> System.out.println("  " + l));

        System.out.println();
        System.out.println("=== mvn dependency:tree (a direct goal, NOT a phase) ===");
        System.out.println("  executes: dependency:tree");
        System.out.println("  lifecycle goals triggered: 0  (no validate/compile/test was run)");
        System.out.println();
        System.out.println("phase count in default lifecycle : " + DEFAULT_LIFECYCLE.length);
        System.out.println("bound plugin executions          : " + BINDINGS.size());
    }
}
